    Bug 1933302 - Make sure last update of in-app notifications is initialized to a sensible value. r=arschmitz

    And extend test to make sure initialization runs

    Differential Revision: https://phabricator.services.mozilla.com/D229994

diff --git a/mail/components/inappnotifications/modules/InAppNotifications.sys.mjs b/mail/components/inappnotifications/modules/InAppNotifications.sys.mjs
index 5049558a19e..bd834760645 100644
--- a/mail/components/inappnotifications/modules/InAppNotifications.sys.mjs
+++ b/mail/components/inappnotifications/modules/InAppNotifications.sys.mjs
@@ -167,6 +167,9 @@ export const InAppNotifications = {
     if (typeof data.seeds !== "object") {
       data.seeds = {};
     }
+    if (!Number.isInteger(data.lastUpdate) || data.lastUpdate > Date.now()) {
+      data.lastUpdate = 0;
+    }
     return data;
   },

diff --git a/mail/components/inappnotifications/test/unit/test_in_app_notifications.js b/mail/components/inappnotifications/test/unit/test_in_app_notifications.js
index efb5cf919f6..a57c5c9f7ab 100644
--- a/mail/components/inappnotifications/test/unit/test_in_app_notifications.js
+++ b/mail/components/inappnotifications/test/unit/test_in_app_notifications.js
@@ -79,6 +79,22 @@ add_task(function test_initializedData() {
     "Should register update callback"
   );
   Assert.ok(NotificationUpdater._interval, "Should initialize updater");
+
+  Assert.deepEqual(
+    InAppNotifications._jsonFile.data.interactedWith,
+    [],
+    "Should initialize interacted with notifications"
+  );
+  Assert.deepEqual(
+    InAppNotifications._jsonFile.data.seeds,
+    {},
+    "Should initialize seeds"
+  );
+  Assert.equal(
+    InAppNotifications._jsonFile.data.lastUpdate,
+    0,
+    "Should initialize lastUpdate to 0"
+  );
 });

